        paint(o, 9, 3, 9); paint(o, 7, 3, 14, 15); paint(o, 7, 3, 18, 19)
        for c in (9,15,18): paint(o, 2, 4, c)
        paint(o, 9, 4, 20)
        paint(o, 1, 5, 9, 12); paint(o, 2, 5, 13); paint(o, 9, 5, 14, 20)
        paint(o, 1, 6, 9); paint(o, 1, 6, 12); paint(o, 9, 6, 20)
        paint(o, 1, 7, 9); paint(o, 1, 7, 12); paint(o, 2, 7, 13); paint(o, 9, 7, 14, 20)
