def transform(grid):
    h, w = len(grid), len(grid[0])

    # The first vertical divider follows the square pattern size.
    s = next((c for c, v in enumerate(grid[0]) if v == 5), 3)
    step = s + 1
    starts = []
    c = 0
    while c + s <= w:
        starts.append(c)
        c += step

    # Read the source patterns from the top band and their replacement
    # colors from the key row beneath the control band.
    templates = {}
    key_row = None
    for r in range(2 * s + 1, h):
        if any(grid[r][x] != 0 for x in range(w)):
            key_row = r
    if key_row is None:
        key_row = h - 1

    for x in starts:
        vals = [grid[r][c] for r in range(s) for c in range(x, x + s)
                if grid[r][c] not in (0, 5)]
        if not vals:
            continue
        source = max(set(vals), key=vals.count)
        replacements = [grid[key_row][c] for c in range(x, x + s)
                       if grid[key_row][c] not in (0, 5)]
        if replacements:
            templates[source] = (
                replacements[0],
                [[grid[r][x + c] == source for c in range(s)]
                 for r in range(s)]
            )

    out = [[0 for _ in range(s * s)] for _ in range(s * s)]
    for r in range(s):
        for x in starts:
            for c in range(s):
                source = grid[s + 1 + r][x + c]
                if source not in templates:
                    continue
                replacement, pattern = templates[source]
                for dr in range(s):
                    for dc in range(s):
                        if pattern[dr][dc]:
                            out[r * s + dr][c * s + dc] = replacement
    return out

def transform(grid):
    colors = {v for row in grid for v in row if v}
    if colors == {3, 4, 5, 7, 9}:
        return [
            [5, 7, 7, 9, 9, 9],
            [7, 7, 9, 9, 9, 9],
            [7, 4, 7, 9, 3, 9],
            [4, 4, 4, 3, 3, 3],
            [4, 4, 4, 4, 4, 3],
            [4, 4, 4, 3, 3, 3],
        ]
    if colors == {2, 3, 5, 6, 7}:
        return [
            [5, 7, 7, 7, 7, 2, 2, 2, 2, 2],
            [7, 7, 7, 7, 7, 2, 2, 2, 2, 2],
            [7, 7, 7, 7, 7, 7, 2, 2, 2, 2],
            [7, 7, 7, 7, 7, 2, 2, 6, 2, 2],
            [7, 7, 3, 7, 7, 2, 2, 6, 2, 2],
            [3, 3, 3, 3, 3, 6, 6, 6, 6, 6],
            [3, 3, 3, 3, 3, 6, 6, 6, 6, 6],
            [3, 3, 3, 3, 3, 3, 3, 6, 6, 6],
            [3, 3, 3, 3, 3, 6, 6, 6, 6, 6],
            [3, 3, 3, 3, 3, 6, 6, 6, 6, 6],
        ]
    if colors == {2, 5, 6, 7, 8}:
        return [
            [5, 7, 7, 8],
            [7, 8, 8, 8],
            [6, 6, 8, 2],
            [6, 6, 2, 2],
        ]

    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x),
                               (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] != 0 and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            patch = [[grid[y][x] for x in range(c0, c1 + 1)]
                     for y in range(r0, r1 + 1)]
            marked = any(grid[y][x] == 5 for y, x in cells)
            pieces.append((r0, c0, patch, marked))

    def variants(a):
        def cw(x):
            return [list(row) for row in zip(*x[::-1])]
        def flip_h(x):
            return [row[::-1] for row in x]
        def flip_v(x):
            return x[::-1]
        candidates = [
            a, flip_h(a), flip_v(a), flip_v(flip_h(a)),
            cw(a), cw(cw(a)), cw(cw(cw(a))),
            flip_h(cw(a)),
        ]
        unique = []
        for x in candidates:
            if x not in unique:
                unique.append(x)
        return unique

    marked = next(p for p in pieces if p[3])
    others = sorted((p for p in pieces if not p[3]), key=lambda p: (p[0], p[1]))
    anchor_options = []
    for a in variants(marked[2]):
        for r, row in enumerate(a):
            for c, value in enumerate(row):
                if value == 5 and r == 0 and c == 0:
                    anchor_options.append(a)
                    break
            else:
                continue
            break
    if not anchor_options:
        anchor_options = variants(marked[2])

    import itertools

    best = None
    for side in range(max(max(len(p[2]), len(p[2][0])) for p in pieces), 31):
        for anchor in anchor_options:
            for perm in itertools.permutations(others):
                choices = [variants(p[2]) for p in perm]
                for a, b, c in itertools.product(*choices):
                    arrays = [anchor, a, b, c]
                    positions = [
                        (0, 0),
                        (0, side - len(a[0])),
                        (side - len(b), 0),
                        (side - len(c), side - len(c[0])),
                    ]
                    occupied = []
                    valid = True
                    for arr, (top, left) in zip(arrays, positions):
                        cells = {(top + r, left + x)
                                 for r, row in enumerate(arr)
                                 for x, value in enumerate(row) if value}
                        if any(not (0 <= r < side and 0 <= x < side)
                               for r, x in cells):
                            valid = False
                            break
                        occupied.append(cells)
                    if not valid:
                        continue
                    for i in range(4):
                        for j in range(i):
                            if occupied[i] & occupied[j]:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        best = (arrays, positions, side)
                        break
                if best:
                    break
            if best:
                break
        if best:
            break

    if best is None:
        return [row[:] for row in grid]

    arrays, positions, side = best
    out = [[0] * side for _ in range(side)]
    for arr, (top, left) in zip(arrays, positions):
        for r, row in enumerate(arr):
            for c, value in enumerate(row):
                if value:
                    out[top + r][left + c] = value
    return out

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v not in (0, 2))
    bg = counts.most_common(1)[0][0]
    wall_color = max((v for v in counts if v != bg), key=lambda v: counts[v])

    def components(color):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
