    candidates = []
    for bg in range(10):
        for comp in components(bg):
            rs = [p[0] for p in comp]
            cs = [p[1] for p in comp]
            top, bottom = min(rs), max(rs)
            left, right = min(cs), max(cs)
            bh, bw = bottom - top + 1, right - left + 1
            if bh < 5 or bw < 5:
                continue
            if (any(grid[top][c] != bg or grid[bottom][c] != bg
                    for c in range(left, right + 1)) or
                any(grid[r][left] != bg or grid[r][right] != bg
                    for r in range(top, bottom + 1))):
