        pts = list(shape)
        forms = []
        for flip in (1, -1):
            for rot in range(4):
                transformed = []
                for r, c in pts:
                    x, y = r, flip * c
                    for _ in range(rot):
                        x, y = y, -x
                    transformed.append((x, y))
                forms.append(normalize(transformed))
