def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full-width rows identify the background color.
    from collections import Counter, deque

    full_rows = [row[0] for row in grid if len(set(row)) == 1]
    background = Counter(full_rows).most_common(1)[0][0] if full_rows else Counter(
        x for row in grid for x in row
    ).most_common(1)[0][0]

    # Find horizontal panel bands: uniform interiors with matching side borders.
    panel_rows = []
    for r, row in enumerate(grid):
        interior = row[1:-1]
        if interior and len(set(interior)) == 1:
            fill = interior[0]
            border = row[0]
            if border != fill and row[-1] == border:
                panel_rows.append((r, fill, border))

    panels = []
    for r, fill, border in panel_rows:
        if panels and panels[-1][1] == r - 1 and panels[-1][2:] == (fill, border):
            panels[-1] = (r, panels[-1][1], fill, border)
        else:
            panels.append((r, r, fill, border))

    if not panels:
        return [row[:] for row in grid]

    source_end = min(top for top, bottom, fill, border in panels)

    # Group touching non-background source cells into objects.
    seen = set()
    objects = []
    for r in range(source_end):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            cells = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                rr, cc = queue.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < source_end and 0 <= nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] != background):
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            objects.append(cells)

    out = [row[:] for row in grid]

    # Remove the source objects.
    for cells in objects:
        for r, c in cells:
            out[r][c] = background

    # Copy each matching object into its panel, bottom-aligned.
    for top, bottom, fill, border in panels:
        candidates = []
        for cells in objects:
            counts = Counter(grid[r][c] for r, c in cells)
            if counts and counts.most_common(1)[0][0] == fill:
                candidates.append(cells)
        if not candidates:
            continue

        cells = max(candidates, key=lambda obj: sum(grid[r][c] == fill for r, c in obj))
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        target_top = bottom - (max_r - min_r)

        for r, c in cells:
            rr = target_top + (r - min_r)
            if top <= rr <= bottom and 1 <= c < w - 1:
                out[rr][c] = border if grid[r][c] == fill else fill

