    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    tiles = []
    size = 5

    # Detect the square tiles by their uniform-colored border and interior.
    for r in range(h - size + 1):
        for c in range(w - size + 1):
            border = grid[r][c]
            if border == bg:
                continue
            if any(grid[r + dy][c + dx] != border
                   for dy in range(size) for dx in range(size)
                   if dy in (0, size - 1) or dx in (0, size - 1)):
                continue
            inside = grid[r + 1][c + 1]
            if inside == bg or any(grid[r + dy][c + dx] != inside
                                   for dy in range(1, size - 1)
                                   for dx in range(1, size - 1)):
                continue
            tiles.append({
                "r": r, "c": c, "border": border,
                "crop": [row[c:c + size] for row in grid[r:r + size]]
            })

    out = [[bg] * w for _ in range(h)]

    for border in {t["border"] for t in tiles}:
        group = [t for t in tiles if t["border"] == border]
        # Preserve left-to-right ordering for tiles whose vertical spans overlap.
        edges = []
        for i, a in enumerate(group):
            for j, b in enumerate(group):
                if i == j:
                    continue
                vertical_overlap = a["r"] < b["r"] + size and b["r"] < a["r"] + size
                if vertical_overlap and a["c"] < b["c"]:
                    edges.append((i, j))

        if border == 8:  # These tiles slide toward the left edge.
            xs = [0] * len(group)
            for i in sorted(range(len(group)), key=lambda k: group[k]["c"]):
                for a, b in edges:
                    if a == i:
                        xs[b] = max(xs[b], xs[a] + size)
        else:  # The other tiles slide toward the right edge.
            xs = [w - size] * len(group)
            for j in sorted(range(len(group)), key=lambda k: group[k]["c"], reverse=True):
                for a, b in edges:
                    if b == j:
                        xs[a] = min(xs[a], xs[b] - size)

        for tile, x in zip(group, xs):
            for dy in range(size):
                for dx in range(size):
                    out[tile["r"] + dy][x + dx] = tile["crop"][dy][dx]

    return out

