def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The divider color is the non-background color with the longest straight run.
    run = {}
    for r in range(h):
        c = 0
        while c < w:
            e = c + 1
            while e < w and grid[r][e] == grid[r][c]:
                e += 1
            run[grid[r][c]] = max(run.get(grid[r][c], 0), e - c)
            c = e
    for c in range(w):
        r = 0
        while r < h:
            e = r + 1
            while e < h and grid[e][c] == grid[r][c]:
                e += 1
            run[grid[r][c]] = max(run.get(grid[r][c], 0), e - r)
            r = e
    wall = max((v for v in counts if v != bg), key=lambda v: run.get(v, 0))

    out = [row[:] for row in grid]
    seen = set()

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == wall or (sr, sc) in seen:
                continue

            comp = set()
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            while q:
                r, c = q.popleft()
                comp.add((r, c))
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                        grid[nr][nc] != wall and (nr,nc) not in seen):
                        seen.add((nr,nc))
                        q.append((nr,nc))

            markers = [(r, c, grid[r][c]) for r, c in comp
                       if grid[r][c] not in (bg, wall)]
            if not markers:
                continue

            r0 = min(r for r, c in comp)
            r1 = max(r for r, c in comp)
            c0 = min(c for r, c in comp)
            c1 = max(c for r, c in comp)

            # Prefer the corner whose inward diagonal contains the clearest
            # sequence of colored marker pixels.
            corners = [
                (r0, c0, 1, 1), (r0, c1, 1, -1),
                (r1, c0, -1, 1), (r1, c1, -1, -1)
            ]
            best = []
            best_score = None
            for ar, ac, dr, dc in corners:
                group = []
                for r, c, color in markers:
                    x, y = (r-ar)*dr, (c-ac)*dc
                    if x == y and x >= 0:
                        group.append((x, color, r, c))
                depths = sorted(set(x for x, _, _, _ in group))
                consecutive = 0
                if depths:
                    consecutive = 1
                    for a, b in zip(depths, depths[1:]):
                        if b == a + 1:
                            consecutive += 1
                        else:
                            consecutive = 1
                score = (len(depths), consecutive, len(set(v for _, v, _, _ in group)))
                if best_score is None or score > best_score:
                    best_score, best = score, group
            if not best:
                best = [(0, color, r, c) for r, c, color in markers]

            # Compute inward layer number by peeling the component boundary.
            layer = {}
            q = deque()
            for r, c in comp:
                if any((nr, nc) not in comp for nr, nc in
                       ((r-1,c), (r+1,c), (r,c-1), (r,c+1))):
                    layer[(r,c)] = 0
                    q.append((r,c))
            while q:
                r, c = q.popleft()
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (nr,nc) in comp and (nr,nc) not in layer:
                        layer[(nr,nc)] = layer[(r,c)] + 1
                        q.append((nr,nc))

            by_depth = {}
            for _, color, r, c in best:
                d = layer.get((r,c), 0)
                by_depth.setdefault(d, []).append(color)
            for d in by_depth:
                by_depth[d] = Counter(by_depth[d]).most_common(1)[0][0]
            ds = sorted(by_depth)
            first = ds[0]

            if len(ds) == 1 and first == 0:
                # A lone corner marker fills its whole compartment.
                palette = [by_depth[0]]
            elif len(ds) == 1:
                color = by_depth[first]
                palette = [bg, color] if first % 2 else [color, bg]
            elif first == 0:
                palette = [by_depth[d] for d in ds]
            else:
                palette = [bg] + [by_depth[d] for d in ds]

            for cell in comp:
                d = layer.get(cell, 0)
                out[cell[0]][cell[1]] = palette[d % len(palette)]

    return out

