                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            ys = [p[0] for p in comp]
            xs = [p[1] for p in comp]
            side = max(ys) - min(ys) + 1
            if (side >= 2 and max(xs) - min(xs) + 1 == side
                    and len(comp) == side * side):
                square_comps.setdefault(color, []).append(comp)

    # The endpoint markers are the color represented by exactly two squares.
    marker_color = next(
        (color for color, comps in square_comps.items() if len(comps) == 2),
        None
    )
    if marker_color is None:
        return out

    markers = square_comps[marker_color]
    start, goal = set(markers[0]), set(markers[1])

    # The thin connecting stroke is a non-background color not forming
    # solid-square objects.
    stroke_colors = [c for c in counts if c != bg and c not in square_comps]
    if not stroke_colors:
        return out
    stroke_color = max(stroke_colors, key=lambda c: counts[c])

    # Search through stroke cells and square objects, linking the two markers.
    allowed = {stroke_color}
    allowed.update(square_comps.keys())
    queue = deque()
    previous = {}
    for p in start:
        queue.append(p)
        previous[p] = None

    finish = None
    while queue:
        r, c = queue.popleft()
        if (r, c) in goal:
            finish = (r, c)
            break
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w):
                    continue
                p = (nr, nc)
                if p in previous or grid[nr][nc] not in allowed:
                    continue
                previous[p] = (r, c)
                queue.append(p)

    if finish is None:
        return out

    route = set()
    p = finish
    while p is not None:
        route.add(p)
        p = previous[p]

    # Highlight the line and recolor any intervening square objects.
    for r, c in route:
        if grid[r][c] == stroke_color:
            out[r][c] = 5

