                    by_cell = {}
                    for i, obj in enumerate(objects):
                        h, w = obj["h"], obj["w"]
                        for r in range(ph - h + 1):
                            for c in range(pw - w + 1):
                                rect = frozenset(
                                    (y, x)
                                    for y in range(r, r + h)
                                    for x in range(c, c + w)
                                )
                                if rect <= mask:
                                    p = (i, r, c, rect)
                                    pi = len(placements)
                                    placements.append(p)
                                    for cell in rect:
                                        by_cell.setdefault(cell, []).append(pi)

                    # Exact-cover search: use every object once and cover the mask.
                    full_unused = (1 << len(objects)) - 1
                    memo = set()

                    def search(rem, unused):
                        if not rem:
                            return () if unused == 0 else None
                        if unused == 0:
                            return None
                        key = (frozenset(rem), unused)
                        if key in memo:
                            return None
                        memo.add(key)

                        best_options = None
                        for cell in rem:
                            opts = []
                            for pi in by_cell.get(cell, ()):
                                i, r, c, rect = placements[pi]
                                if (unused >> i) & 1 and rect <= rem:
                                    opts.append(pi)
                            if not opts:
                                return None
                            if best_options is None or len(opts) < len(best_options):
                                best_options = opts
                                if len(opts) == 1:
                                    break

                        best_options.sort(
                            key=lambda pi: -objects[placements[pi][0]]["h"]
                                             * objects[placements[pi][0]]["w"]
                        )
                        for pi in best_options:
                            i, r, c, rect = placements[pi]
                            tail = search(rem - rect, unused ^ (1 << i))
                            if tail is not None:
                                return (pi,) + tail
                        return None

                    solution = search(mask, full_unused)
                    if solution is None:
                        continue

                    out = [[base for _ in range(pw)] for _ in range(ph)]
                    for pi in solution:
                        i, r, c, rect = placements[pi]
                        for dy, dx, value in objects[i]["cells"]:
                            out[r + dy][c + dx] = value

                    border_ratio = Counter(border)[base] / len(border)
                    yield (border_ratio, ph * pw, out)

    candidates = list(panel_candidates())
    if candidates:
        candidates.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return candidates[0][2]
    return [row[:] for row in grid]
